import{_ as t,a as r}from"./chunks/linebox_runtime.CTuWgwg1.js";import{_ as s,o as a,c as g,a3 as n,j as e}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"SVG LineBox – Linienwerte sammeln und weitergeben","description":"","frontmatter":{"title":"SVG LineBox – Linienwerte sammeln und weitergeben"},"headers":[],"relativePath":"projects/grafik-visual-studio/svg-linebox.md","filePath":"projects/grafik-visual-studio/svg-linebox.md","lastUpdated":1793128957000}'),o={name:"projects/grafik-visual-studio/svg-linebox.md"};function d(l,i,u,h,m,b){return a(),g("div",null,[...i[0]||(i[0]=[n('<h1 id="svg-linebox" tabindex="-1">SVG LineBox <a class="header-anchor" href="#svg-linebox" aria-label="Permalink to &quot;SVG LineBox&quot;">​</a></h1><p>Ab Studio 0.1.136 bietet die Ausgangslinie zusätzlich <strong>Teiler automatisch anpassen (SVG LineBox)</strong> mit eigener Zielgeschwindigkeit (0,05–5 Zyklen/s, Standard 1). Damit bleiben auch große Summen gut einstellbar animiert. Diese Option ist unabhängig von der Teilerautomatik für Zahlen-Entitäten; siehe <a href="./svg-line">SVG-Line</a>.</p><p>Die <strong>SVG LineBox</strong> unter <strong>HA Grafik – Spezial</strong> sammelt Zahlenwerte verbundener SVG-Lines, bildet eine vorzeichenbehaftete Summe und kann sie an Ausgangslinien sowie optional an einen Home-Assistant-Zahlenhelfer weitergeben. Im Editor ist der Kasten sichtbar. In der Runtime verschwindet er; aktive Leitungen treffen sich optisch in seiner Mitte.</p><h2 id="im-editor-einrichten" tabindex="-1">Im Editor einrichten <a class="header-anchor" href="#im-editor-einrichten" aria-label="Permalink to &quot;Im Editor einrichten&quot;">​</a></h2><ol><li>Füge eine <strong>SVG LineBox</strong> und die benötigten <strong>SVG-Lines</strong> ein.</li><li>Aktiviere bei der LineBox <strong>Andockpunkte</strong> und nur die benötigten Positionen. Anfangs sind alle zwölf aus. <strong>Alle Punkte</strong> schaltet sie gemeinsam ein oder aus; jede Position kann auch einzeln gewählt werden.</li><li>Unter <strong>Anschlüsse</strong> erscheint für jeden aktiven Punkt die Rolle <strong>Eingang</strong>, <strong>Nullstellung</strong> oder <strong>Ausgang</strong>. <strong>Nullstellung</strong> ist der Standard und nimmt nicht an der Berechnung teil. Für deaktivierte Punkte gibt es keine Rollenwahl.</li><li>Verbinde die Eingangsleitungen mit Eingängen und eine weitere SVG-Line mit einem Ausgang. Ab Studio 0.1.126 kann eine Leitung den Wert eines am anderen Ende verbundenen numerischen Widgets übernehmen, etwa Number. Alternativ wählst du unter <strong>Animation → Richtungsquelle</strong> eine <strong>Zahlen-Entität</strong>; diese eigene Linienquelle hat Vorrang.</li><li>Aktiviere am Ausgang <strong>Berechneten Wert weitergeben</strong> und an der Ausgangslinie <strong>Animation aktivieren</strong>. Erst dann steuert die Summe deren Richtung und Geschwindigkeit.</li></ol><p>Die Andockpunkte haben dieselben zwölf Positionen wie bei anderen Widgets: links/rechts je oben, Mitte, unten; oben/unten je bei 1/4, Mitte und 3/4. Du kannst mehrere Linien an einem Punkt anschließen. <strong>Eingang</strong> und <strong>Ausgang</strong> bestimmen die Funktion, nicht allein die optische Richtung der Linie.</p>',6),e("video",{controls:"",playsinline:"",preload:"metadata",style:{width:"100%","max-width":"960px"},"aria-label":"SVG LineBox im Editor bearbeiten"},[e("source",{src:t,type:"video/mp4"}),e("a",{href:"/videos/grafik-visual-studio/linebox_edit.mp4"},"Editor-Video öffnen")],-1),n('<p><a href="/videos/grafik-visual-studio/linebox_edit.mp4">Editor-Video direkt öffnen</a></p><h2 id="wie-die-summe-entsteht" tabindex="-1">Wie die Summe entsteht <a class="header-anchor" href="#wie-die-summe-entsteht" aria-label="Permalink to &quot;Wie die Summe entsteht&quot;">​</a></h2><p>Die LineBox berücksichtigt sichtbare SVG-Lines an <strong>Eingängen</strong> mit einem gültigen Zahlenwert. Eine explizite Zahlen-Entität der Linie hat Vorrang; ohne sie wird der Wert vom verbundenen numerischen Widget oder einem freigegebenen LineBox-Ausgang übernommen. Bei Number wird der Multiplikator berücksichtigt, ohne die Anzeige zu runden. Die Animation einer manuellen Eingangsleitung bleibt unabhängig von der Wertübernahme. Für eigene Linienwerte gilt: Endet die Leitung an der LineBox, geht ihr Wert mit seinem Vorzeichen in die Summe ein; beginnt sie dort, zählt er mit umgekehrtem Vorzeichen. Automatisch übernommene Widget-Werte werden entsprechend der Leitungsorientierung umgerechnet. Jede Leitung wird höchstens einmal gezählt. Fehlende oder ungültige Zustände werden ausgelassen; ohne gültigen Eingang gibt es keinen berechneten Wert. Null ist gültig. Interne Rückkopplungsschleifen werden abgebrochen.</p><p><strong>Beispiel ohne zusätzliche Helfer:</strong> Number mit 125 und Number mit 79 über zwei Leitungen an Eingänge anschließen: Die LineBox zeigt <strong>204</strong>. Verbinde den freigegebenen Ausgang mit einem weiteren Number, Red Number, Gauge oder Bar. Dort unter <strong>Wertquelle → Wert vom Dockpunkt</strong> den <strong>Eingangs-Dockpunkt</strong> wählen und unter <strong>Andockpunkte</strong> aktivieren. Die Anzeige übernimmt den Wert direkt; mehrere gültige Linien an diesem Punkt werden vorzeichenbehaftet summiert. Ohne gültigen Wert erscheint <code>--</code>. Die übrigen Quellen sind <strong>Home-Assistant-Entität / Vorschau</strong> (bisheriges Verhalten) und <strong>Vorschauwert</strong> (ignoriert eine eingetragene Entität).</p><p>Beispiel: Zwei Eingangsleitungen enden an der LineBox mit <code>1000</code> und <code>-300</code>. Die Summe ist <code>700</code>. Bei einer dritten Leitung, die an einem <strong>Ausgang</strong> beginnt und dort <strong>Berechneten Wert weitergeben</strong> aktiviert hat, bedeutet <code>700</code> Fluss vom Anfang zum Ende. Endet die Ausgangsleitung an der Box, wird das Vorzeichen für ihre Orientierung umgekehrt. Ihre Farben, Pfeilspitzen und Linienart bleiben ihre eigenen. Ist ihre Animation ausgeschaltet, bleibt sie auch bei einem übergebenen Wert stehen; <code>0</code> oder kein gültiger Eingang stoppt sie ebenfalls. Mit <strong>SVG LineBox-Teiler (bei Übergabe)</strong> an der Ausgangslinie ergibt <code>700 ÷ 100 = 7</code> Zyklen/s. Die allgemeine Grenze der Zahlenanimation liegt bei 0,05–20 Zyklen/s.</p><p>Bei <strong>Nullstellung</strong> nimmt ein Punkt weder an Summe noch Ausgabe teil. Schalte <strong>Berechneten Wert weitergeben</strong> an einem Ausgang aus, wenn die angeschlossene SVG-Line wieder allein durch ihre eigenen Animationseinstellungen gesteuert werden soll. Eine bloße Linienkreuzung koppelt nichts.</p><h2 id="verbindungspunkt-und-runtime" tabindex="-1">Verbindungspunkt und Runtime <a class="header-anchor" href="#verbindungspunkt-und-runtime" aria-label="Permalink to &quot;Verbindungspunkt und Runtime&quot;">​</a></h2><p>Aktive Leitungen werden in der Runtime zur Mitte der unsichtbaren Box geführt. Die Gruppe <strong>Verbindungspunkt</strong> steuert die Darstellung:</p><table tabindex="0"><thead><tr><th>Eigenschaft</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Kreis anzeigen</strong></td><td>Blendet den Kreis über den Leitungsenden ein oder aus. Standard: ein. Er erscheint bei mindestens zwei sichtbaren angeschlossenen Leitungen.</td></tr><tr><td><strong>Durchmesser (px)</strong></td><td>Gewünschter Kreisdurchmesser von 4–100 px; bei dicken Leitungen wächst er bei Bedarf, damit die Enden verdeckt bleiben.</td></tr><tr><td><strong>Füllfarbe</strong>, <strong>Randfarbe</strong>, <strong>Randbreite (px)</strong></td><td>Farben und Randstärke des Kreises; die Randbreite lässt sich von 0–20 px einstellen.</td></tr><tr><td><strong>Ausgabewert anzeigen</strong></td><td><strong>Aus</strong> (Standard), <strong>Über dem Kreis</strong> oder <strong>Unter dem Kreis</strong>. Zeigt die signierte Eingangssumme; ohne gültigen Eingang erscheint ein Gedankenstrich. Die Anzeige kann auch bei ausgeblendetem Kreis genutzt werden.</td></tr></tbody></table><p>Der angezeigte Wert aktualisiert sich in der Runtime auch während einer Sliderbewegung. Der Kreis liegt optisch über den verbundenen Leitungen und verdeckt ihre kantigen Enden.</p>',10),e("video",{controls:"",playsinline:"",preload:"metadata",style:{width:"100%","max-width":"960px"},"aria-label":"SVG LineBox in der Runtime"},[e("source",{src:r,type:"video/mp4"}),e("a",{href:"/videos/grafik-visual-studio/linebox_runtime.mp4"},"Runtime-Video öffnen")],-1),n('<p><a href="/videos/grafik-visual-studio/linebox_runtime.mp4">Runtime-Video direkt öffnen</a></p><h2 id="optionaler-home-assistant-zahlenhelfer" tabindex="-1">Optionaler Home-Assistant-Zahlenhelfer <a class="header-anchor" href="#optionaler-home-assistant-zahlenhelfer" aria-label="Permalink to &quot;Optionaler Home-Assistant-Zahlenhelfer&quot;">​</a></h2><p>Die Übergabe an Ausgangslinien funktioniert intern und benötigt keinen Helfer. Wenn du die Summe auch in Home Assistant weiterverarbeiten möchtest, aktiviere unter <strong>Zahlenhelfer-Ausgabe</strong> <strong>Zusätzlich an Zahlenhelfer schreiben</strong> und wähle einen vorhandenen <code>input_number.*</code>-Helfer. In der Runtime schreibt die App nur bei geändertem Wert; kurze Änderungen werden zusammengefasst. Der erlaubte Wertebereich des Helfers muss die mögliche Summe umfassen. Ist derselbe Helfer zugleich Zahlenquelle einer Eingangsleitung dieser LineBox, wird die Ausgabe zur Vermeidung einer direkten Rückkopplung verweigert. Ohne gültigen Eingang erfolgt kein Schreibvorgang.</p><p>Die erste Version liest Zahlen-Entitäten über die Eingangsleitungen. Eine eigene Entitätssteuerung pro Anschluss ist noch nicht vorhanden. Der frühere Palettenname <strong>Linebox</strong> bleibt als Suchbegriff erhalten; gespeicherte Projekte behalten den technischen Typ <code>linebox</code> und bestehende eigene Widget-Namen.</p><p>Weitere Einstellungen zu Verlauf, Farben, Pfeilen und Animation findest du bei <a href="./svg-line">SVG-Line</a>.</p>',5)])])}const f=s(o,[["render",d]]);export{k as __pageData,f as default};
